<script module lang="ts">
/**
 * Loading placeholder that holds the layout while content arrives (`design/components/skeleton.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/skeleton.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { joinSlot, type SpaceStep } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/skeleton.module.css'

export type SkeletonShape = NonNullable<SkeletonProps['shape']>

export interface SkeletonProps {
  /**
   * Set when the skeleton stands for a named region; makes the root a `role="status"` with this
   * name. Otherwise it is hidden, because a grey box means nothing to a screen reader.
   */
  label?: string
  shape?: 'text' | 'rect' | 'circle'
  size?: SpaceStep
  /**
   * The step whose line box this stands in for.
   */
  textStep?: 'sm' | 'md' | 'lg' | 'xs' | 'xl' | '2xl' | '3xl'
  /**
   * A space step, or the full width of whatever holds it.
   */
  width?: SpaceStep | 'full'
}
</script>

<script lang="ts">
let { label: labelOwn, shape = 'text', size, textStep, width }: SkeletonProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const step = $derived(shape === 'text' ? (textStep ?? 'md') : undefined)
const span = $derived(shape === 'circle' ? undefined : (width ?? 'full'))
const named = $derived(label !== undefined)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    class={styles.skeleton}
    data-shape={shape}
    data-text-step={step}
    data-width={span === undefined ? undefined : String(span)}
    data-size={size === undefined ? undefined : String(size)}
    role={(named) ? 'status' : undefined}
    aria-label={label}
    aria-hidden={(!named) ? true : undefined}
    data-member="skeleton"
  ></div
>{/if
}{@render joined.end?.()}
